<?php

declare(strict_types=1);

require __DIR__ . '/config/database.php';
require __DIR__ . '/includes/functions.php';

$dosenId = get_int_query('id');
$dosen = table_exists('view_dosen_lengkap') ? fetch_one('SELECT * FROM view_dosen_lengkap WHERE dosen_id = :id', ['id' => $dosenId]) : fetch_one('SELECT * FROM dosen WHERE dosen_id = :id', ['id' => $dosenId]);
if ($dosen === null) {
    http_response_code(404);
    exit('Data dosen tidak ditemukan.');
}
$classes = table_exists('view_kelas_lengkap') ? fetch_all('SELECT * FROM view_kelas_lengkap WHERE dosen_id = :id ORDER BY nama_matakuliah, kelas_id', ['id' => $dosenId]) : fetch_all("SELECT k.*, m.nama_matakuliah, m.semester, m.sks, r.total_essays, r.main_q, r.main_category, r.main_recommendation, r.priority_q, r.strength_q, r.monitoring_q FROM kelas k JOIN matakuliah m ON m.matakuliah_id = k.matakuliah_id LEFT JOIN rekomendasi_kelas r ON r.kelas_id = k.kelas_id WHERE k.dosen_id = :id ORDER BY m.nama_matakuliah, k.kelas_id", ['id' => $dosenId]);
$sentiment = weighted_dosen_sentiment($classes);
$totalEssays = array_sum(array_map(static fn (array $row): int => (int) ($row['total_essays'] ?? $row['jumlah_essay'] ?? 0), $classes));
$uniqueCourses = count(array_unique(array_column($classes, 'matakuliah_id')));
$pageTitle = 'Detail ' . $dosen['nama_dosen'];
require __DIR__ . '/includes/header.php';
require __DIR__ . '/includes/navbar.php';
?>
<main class="container py-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><div class="d-flex gap-3 no-print mb-2"><a href="javascript:history.back()" class="text-decoration-none">Kembali</a><a href="index.php" class="text-decoration-none">Beranda</a></div><h1 class="h3 mt-2 mb-1"><?= e($dosen['nama_dosen']) ?></h1><p class="text-secondary mb-0">ID dosen <?= (int) $dosenId ?></p></div><div class="d-flex gap-2 no-print"><a class="btn btn-primary" href="statistik.php?type=dosen&id=<?= (int) $dosenId ?>">Lihat statistik</a><button class="btn btn-outline-secondary" type="button" onclick="window.print()">Cetak</button></div></div>
<section class="row g-3 mb-4"><div class="col-6 col-lg-3"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Kelas dianalisis</div><div class="metric-value mt-2"><?= format_integer(count($classes)) ?></div></div></div></div><div class="col-6 col-lg-3"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Mata kuliah</div><div class="metric-value mt-2"><?= format_integer($uniqueCourses) ?></div></div></div></div><div class="col-6 col-lg-3"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Total esai</div><div class="metric-value mt-2"><?= format_integer($totalEssays ?: ($dosen['total_essay'] ?? 0)) ?></div></div></div></div><div class="col-6 col-lg-3"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Kategori dominan</div><div class="fw-semibold mt-2"><?= e(category_label($dosen['kategori_dominan'] ?? null)) ?></div></div></div></div></section>
<section class="row g-4 mb-4"><div class="col-lg-5"><div class="card content-card h-100"><div class="card-body p-4"><h2 class="h5">Sentimen gabungan seluruh kelas</h2><p class="small text-secondary">Persentase dihitung dengan pembobot jumlah esai pada setiap kelas.</p><?php foreach ([['positive','Positif','bg-success'],['neutral','Netral','bg-secondary'],['negative','Negatif','bg-danger']] as $item): ?><div class="d-flex justify-content-between mt-3"><span><?= e($item[1]) ?></span><strong><?= number_format($sentiment[$item[0]], 1, ',', '.') ?>%</strong></div><div class="progress"><div class="progress-bar <?= e($item[2]) ?>" style="width: <?= e($sentiment[$item[0]]) ?>%"></div></div><?php endforeach; ?></div></div></div><div class="col-lg-7"><div class="card content-card h-100"><div class="card-body p-4"><h2 class="h5">Ringkasan analisis dosen</h2><dl class="row mb-0 mt-3"><dt class="col-sm-6">Aspek prioritas dominan</dt><dd class="col-sm-6"><?= e($dosen['q_paling_sering_jadi_prioritas'] ?? $dosen['top_priority_q'] ?? '-') ?></dd><dt class="col-sm-6">Aspek paling bermasalah</dt><dd class="col-sm-6"><?= e($dosen['q_paling_bermasalah'] ?? '-') ?></dd><dt class="col-sm-6">Kelas perlu perbaikan</dt><dd class="col-sm-6"><?= format_percent($dosen['pct_kelas_perlu_perbaikan'] ?? 0) ?></dd><dt class="col-sm-6">Sentimen dominan</dt><dd class="col-sm-6"><span class="badge <?= e(sentiment_badge($dosen['sentimen_dominan'] ?? null)) ?>"><?= e(ucfirst((string) ($dosen['sentimen_dominan'] ?? 'belum tersedia'))) ?></span></dd></dl></div></div></div></section>
<section class="card content-card"><div class="card-body p-4"><h2 class="h5 mb-1">Kelas yang diampu</h2><p class="text-secondary">Rekomendasi tetap disajikan pada tingkat kelas agar perbedaan pengalaman belajar antarkelas tidak hilang.</p><?php if ($classes === []): ?><div class="alert alert-light border mb-0">Belum ada kelas yang terhubung dengan dosen ini.</div><?php else: ?><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Kelas</th><th>Mata kuliah</th><th>Esai</th><th>Sentimen dominan</th><th>Aspek utama</th><th>Kategori</th><th>Rekomendasi</th><th></th></tr></thead><tbody><?php foreach ($classes as $class): ?><tr><td><?= e($class['nama_kelas'] ?: 'Kelas ' . $class['kelas_id']) ?></td><td><a href="detail_matakuliah.php?id=<?= (int) $class['matakuliah_id'] ?>" class="link-primary text-decoration-none"><?= e($class['nama_matakuliah']) ?></a></td><td><?= format_integer($class['total_essays'] ?? $class['jumlah_essay'] ?? 0) ?></td><td><span class="badge <?= e(sentiment_badge($class['sentimen_dominan'] ?? null)) ?>"><?= e(ucfirst((string) ($class['sentimen_dominan'] ?? '-'))) ?></span></td><td><?= e($class['main_q'] ?? '-') ?></td><td><span class="badge <?= e(category_badge($class['main_category'] ?? null)) ?>"><?= e(category_label($class['main_category'] ?? null)) ?></span></td><td><?= e($class['main_recommendation'] ?? '-') ?></td><td><a class="btn btn-sm btn-outline-primary" href="detail_kelas.php?id=<?= (int) $class['kelas_id'] ?>">Lihat</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section></main>
<?php require __DIR__ . '/includes/footer.php'; ?>
